using ReeLib;using ReeLib.Mot;using System.Numerics;using System.Text.Json;
Directory.SetCurrentDirectory("E:/CodexPepo/RE_Research");
var files=JsonDocument.Parse(File.ReadAllText("reports/phase2/effective_files.json")).RootElement;
float[] V(Vector3 v)=>[v.X,v.Y,v.Z]; float[] Q(Quaternion q){q=Quaternion.Normalize(q);return [q.X,q.Y,q.Z,q.W];}
object? TrackData(Track? t,bool rot=false){if(t==null)return null;float[][]? v=rot?t.rotations?.Select(Q).ToArray():t.translations?.Select(V).ToArray();if(v==null||v.Length==0)return null;var fps=t.frameRate>0?t.frameRate:60;var times=Enumerable.Range(0,v.Length).Select(i=>(t.frameIndexes is {Length:>0}?t.frameIndexes[Math.Min(i,t.frameIndexes.Length-1)]:i)/(float)fps).ToArray();if(v.SelectMany(x=>x).Any(x=>!float.IsFinite(x)))throw new Exception("Nonfinite track");return new{times,values=v};}
var clips=new List<object>();var wanted=new HashSet<int>{120,122,124,126,140,160,165,167,161,1100,1200,1201};
foreach(var e in files.EnumerateArray()){var path=e.GetProperty("Path").GetString()!;bool add=path.EndsWith("/ch0100_handgun00h_add.motlist.1047");if(!add&&!path.EndsWith("/ch0100_handgun00h.motlist.1047"))continue;using var f=new MotlistFile(new FileHandler(e.GetProperty("File").GetString()!));if(!f.Read())throw new Exception("Read failure");foreach(var entry in f.Motions){if(!wanted.Contains(entry.motNumber)||(add&&entry.motNumber<1200)||entry.MotFile is not MotFile m)continue;var bones=m.Bones; if(bones.Count==0)throw new Exception("No skeleton");var hashes=bones.Select(b=>b.boneHash).ToHashSet();if(m.BoneClips.Any(c=>!hashes.Contains(c.ClipHeader.boneHash)))throw new Exception("Unmapped bone");var tracks=m.BoneClips.Select(c=>new{bone=bones.FindIndex(b=>b.boneHash==c.ClipHeader.boneHash),position=TrackData(c.Translation),rotation=TrackData(c.Rotation,true),scale=TrackData(c.Scale)}).ToArray();clips.Add(new{id=entry.motNumber,bank=add?2100:100,name=m.Header.motName,additive=add,frames=m.Header.frameCount,fps=m.Header.FrameRate,duration=m.Header.frameCount/Math.Max(1,(int)m.Header.FrameRate),source=path,bones=bones.Select(b=>new{name=b.boneName,parent=b.Parent==null?-1:bones.IndexOf(b.Parent),position=V(b.translation),rotation=Q(b.quaternion)}).ToArray(),tracks});Console.WriteLine($"{m.Header.motName}: {bones.Count} bones, {tracks.Length} tracks");}}
var json=JsonSerializer.Serialize(new{version=1,character="ch0100 / Leon",clips});File.WriteAllText("player/dist/motions.js","window.MOTION_DATA="+json+";");File.WriteAllText("player/dist/motions.json",json);Console.WriteLine($"Exported {clips.Count} clips");
